# Load Hecke, your lattice definitions, Torus.jl, and TorusHom.jl first.
# Define Torus BEFORE defining torus_cache, and load Torus before TorusHom.
# This suite tests the interface pasted in the chat; it installs no replacement
# methods. It has been written but NOT executed.
using Test

@testset "Torus points and morphisms" begin
    # Genuine divisor lattices of ranks 2, 3, 1, and 0.
    # The finite divisors above distinct x-values have disjoint supports.
    kx, x = Hecke.rational_function_field(QQ, :x)
    ky, y = Hecke.polynomial_ring(kx, :y)
    F, t = Hecke.function_field(y^2 - x)
    O = Hecke.finite_maximal_order(F)
    D1, D2, D3 = [Hecke.divisor(Hecke.ideal(O, x - c)) for c in 1:3]

    L = divisor_lattice([D1, D2])
    K = divisor_lattice([D1, D2, D3])
    N = divisor_lattice([D1])
    Z = divisor_lattice(F, Divisor[])
    Lother = divisor_lattice([D1, D2])

    T, U, V, E = dual(L), dual(K), dual(N), dual(Z)
    Tother = dual(Lother)

    # Explicit QQBar vectors avoid depending on the scalar-varargs constructor
    # when setting up the points used throughout the suite.
    p = T(QQBarFieldElem[2, 3])
    q = T(QQBarFieldElem[5, 7])

    @testset "Torus construction, caching, and parents" begin
        @test T isa Torus{typeof(L)}
        @test character_lattice(T) === L
        @test dual(T) === L
        @test dual(L) === T
        @test dual(dual(T)) === T
        @test dim(T) == 2
        @test dim(U) == 3
        @test dim(E) == 0
        @test T == dual(L)
        @test T != Tother
        @test T !== Tother

        # torus(L) is the uncached constructor in the supplied implementation.
        uncached = torus(L)
        @test uncached !== T
        @test uncached == T
        @test character_lattice(uncached) === L
        @test parent(p) === T
        @test p != Tother(QQBarFieldElem[2, 3])
        @test p != uncached(QQBarFieldElem[2, 3])
    end

    @testset "Point constructors and validation" begin
        @test p isa TorusPoint
        @test p == T(2, 3)
        @test p == T(QQBar(2), QQBar(3))
        @test p == T(reshape(QQBarFieldElem[2, 3], 1, 2))
        @test p == torus_point(T, reshape(QQBarFieldElem[2, 3], 1, 2))
        @test T(1 // 2, 3) == T(QQBarFieldElem[QQBar(1) / 2, QQBar(3)])
        @test coordinates(p) isa Matrix{QQBarFieldElem}
        @test size(coordinates(p)) == (1, 2)
        @test coordinates(p) == reshape(QQBarFieldElem[2, 3], 1, 2)

        @test_throws AssertionError T(QQBarFieldElem[2])
        @test_throws AssertionError T(QQBarFieldElem[2, 3, 4])
        @test_throws AssertionError T(reshape(QQBarFieldElem[2, 3], 2, 1))
        @test_throws AssertionError T(QQBarFieldElem[0, 3])
        @test_throws AssertionError T(QQBarFieldElem[2, 0])
    end

    @testset "Point arithmetic" begin
        @test p * q == T(10, 21)
        @test p * q == q * p
        @test (p * q) * p == p * (q * p)
        @test p + q == p * q                 # Your additive alias.
        @test p // q == T(QQBar(2) / 5, QQBar(3) / 7)
        @test p - q == p // q                # Your subtraction alias.
        @test (p // q) * q == p
        @test p // p == one(T)
        @test p * one(T) == p
        @test one(p) == one(T)
        @test isone(one(T))
        @test !isone(p)
        @test p^0 == one(T)
        @test p^3 == T(8, 27)
        @test p^(-2) == T(QQBar(1) / 4, QQBar(1) / 9)
        @test p * p^(-1) == one(T)
        @test (p * q)^3 == p^3 * q^3

        # In this API scalar * point multiplies each coordinate by the scalar;
        # it is different from the integer group action point^n.
        @test QQBar(2) * p == T(4, 6)
        @test 2 * p == T(4, 6)
        @test p * 2 == T(4, 6)
        @test (1 // 2) * p == T(1, QQBar(3) / 2)
        @test p // QQBar(2) == T(1, QQBar(3) / 2)
        @test_throws AssertionError 0 * p

        alpha = sqrt(QQBar(2))
        @test T(alpha, inv(alpha))^2 == T(2, QQBar(1) / 2)
        imaginary_unit = sqrt(QQBar(-1))
        @test T(imaginary_unit, 1)^2 == T(-1, 1)

        # A rational power chooses roots. Check only this positive-real example;
        # do not assume rational powers define group homomorphisms globally.
        @test (T(4, 9)^(1 // 2))^2 == T(4, 9)

        @test_throws AssertionError p * Tother(2, 3)
        @test_throws AssertionError p // Tother(2, 3)
    end

    @testset "Evaluation on characters" begin
        e1, e2 = L(1, 0), L(0, 1)
        a, b = L(2, -1), L(-1, 3)

        @test evaluate(p, e1) == QQBar(2)
        @test evaluate(p, e2) == QQBar(3)
        @test p(a) == QQBar(4) / 3
        @test p(a + b) == p(a) * p(b)
        @test p(-a) == inv(p(a))
        @test p(3 * a) == p(a)^3
        @test (p * q)(a) == p(a) * q(a)
        @test p(L(0, 0)) == one(QQBar)
        @test_throws AssertionError p(Lother(2, -1))
    end

    # Source rows, target columns: f(x,y) = (x, x^2*y, y).
    A = matrix(ZZ, 2, 3, [1, 2, 0, 0, 1, 1])
    B = matrix(ZZ, 3, 2, [1, 0, 0, 1, 1, 1])
    f, g = hom(T, U, A), hom(U, T, B)

    @testset "Morphism constructors and evaluation" begin
        @test f isa TorusHom{typeof(T), typeof(U)}
        @test domain(f) === T
        @test codomain(f) === U
        @test matrix(f) == A
        @test size(matrix(f)) == (2, 3)
        @test matrix(hom(T, U, [[1, 2, 0], [0, 1, 1]])) == A
        @test f(p) == U(2, 12, 3)
        @test parent(f(p)) === U
        @test f(p * q) == f(p) * f(q)
        @test f(p^(-1)) == f(p)^(-1)
        @test f(one(T)) == one(U)
        @test f(p^3) == f(p)^3

        negative = hom(T, T, matrix(ZZ, 2, 2, [1, -1, 0, 1]))
        @test negative(p) == T(2, QQBar(3) / 2)
        trivial = hom(T, U, zero_matrix(ZZ, 2, 3))
        @test trivial(p) == one(U)

        @test_throws AssertionError f(Tother(2, 3))
        @test_throws AssertionError hom(T, U, identity_matrix(ZZ, 2))
        @test_throws AssertionError hom(T, U, [[1, 2, 0]])
        @test_throws AssertionError hom(T, U, [[1, 2, 0], [0, 1]])

        supplied = deepcopy(A)
        copied_map = hom(T, U, supplied)
        supplied[1, 1] = 99
        @test matrix(copied_map) == A
        @test copied_map(p) == f(p)
    end

    @testset "Identity, composition, and duality" begin
        idT, idU = identity(T), identity(U)
        @test domain(idT) === T
        @test codomain(idT) === T
        @test matrix(idT) == identity_matrix(ZZ, 2)
        @test idT(p) == p
        @test idT(one(T)) == one(T)
        @test (idT * f)(p) == f(p)
        @test (f * idU)(p) == f(p)

        @test g(f(p)) == T(6, 36)
        @test (f * g)(p) == g(f(p))  # First f, then g.
        @test matrix(f * g) == A * B
        @test domain(f * g) === T
        @test codomain(f * g) === T
        @test_throws AssertionError f * identity(T)
        @test_throws AssertionError identity(T) * hom(Tother, U, A)

        df = dual(f)
        @test df isa LatticeHom
        @test domain(df) === K
        @test codomain(df) === L
        @test matrix(df) == transpose(A)
        @test df(K(2, -1, 3)) == L(0, 2)
        @test domain(dual(df)) === T
        @test codomain(dual(df)) === U
        @test matrix(dual(df)) == A
        @test dual(df)(p) == f(p)
        @test dual(f * g) == dual(g) * dual(f)

        # The defining compatibility between point maps and character maps.
        character = K(2, -1, 3)
        @test f(p)(character) == p(df(character)) == QQBar(9)

        h = hom(L, K, A)
        dh = dual(h)
        @test domain(dh) === U
        @test codomain(dh) === T
        @test matrix(dh) == transpose(A)
        @test dh(U(2, 3, 5)) == T(18, 15)
        @test dual(dh) == h
    end

    @testset "Injectivity and surjectivity" begin
        square = hom(V, V, matrix(ZZ, 1, 1, [2]))
        @test square(V(-1)) == one(V)
        @test !is_injective(square)          # Kernel contains -1.
        @test is_surjective(square)         # Every algebraic number has a square root.
        @test !is_bijective(square)

        primitive = hom(V, T, matrix(ZZ, 1, 2, [2, 3]))
        nonprimitive = hom(V, T, matrix(ZZ, 1, 2, [2, 4]))
        @test is_injective(primitive)
        @test !is_surjective(primitive)
        @test !is_injective(nonprimitive)
        @test !is_surjective(nonprimitive)
        @test is_injective(f)
        @test !is_surjective(f)
        @test !is_injective(g)
        @test is_surjective(g)
        @test is_bijective(identity(T))
        shear = hom(T, T, matrix(ZZ, 2, 2, [1, 1, 0, 1]))
        @test is_bijective(shear)
        trivial = hom(T, U, zero_matrix(ZZ, 2, 3))
        @test !is_injective(trivial)
        @test !is_surjective(trivial)
    end

    @testset "Zero-dimensional tori" begin
        e = one(E)
        @test E() == e
        @test size(coordinates(e)) == (1, 0)
        @test isone(e)
        @test e * e == e
        @test e // e == e
        @test e^(-2) == e
        # Construct the zero character by an explicitly sized matrix.
        @test e(Z(zero_matrix(ZZ, 1, 0))) == one(QQBar)

        from_zero = hom(E, T, zero_matrix(ZZ, 0, 2))
        to_zero = hom(T, E, zero_matrix(ZZ, 2, 0))
        @test from_zero(e) == one(T)
        @test to_zero(p) == e
        @test identity(E)(e) == e
        @test size(matrix(identity(E))) == (0, 0)
        @test is_injective(from_zero)
        @test !is_surjective(from_zero)
        @test !is_injective(to_zero)
        @test is_surjective(to_zero)
        @test is_bijective(identity(E))
        @test matrix(hom(E, T, Vector{Int}[])) == zero_matrix(ZZ, 0, 2)
        @test matrix(hom(T, E, [Int[], Int[]])) == zero_matrix(ZZ, 2, 0)
    end

    @testset "Display" begin
        @test occursin("Hom(L,Gm)", sprint(show, T))
        @test occursin("vector of algebraic numbers", sprint(show, p))
        @test occursin("Represented by matrix", sprint(show, f))
    end
end
